SELECT * FROM inventory_balance
WHERE warehouse_id = #{warehouseId}
  AND sku_id = #{skuId}
  AND deleted = FALSE
FOR UPDATE

SELECT * FROM inventory_balance
WHERE warehouse_id = #{warehouseId}
  AND sku_id = #{skuId}
  AND deleted = FALSE

SELECT b.id, b.warehouse_id, b.sku_id, b.unit, b.quantity, b.reserved_quantity, b.version, b.updated_at, w.warehouse_code, w.name AS warehouse_name, k.sku_code, k.spec_name AS sku_name, k.spec_values, p.name AS product_name FROM inventory_balance b LEFT JOIN warehouse w ON w.id = b.warehouse_id LEFT JOIN product_sku k ON k.id = b.sku_id LEFT JOIN product_spu p ON p.id = k.spu_id WHERE b.deleted = FALSE
AND b.warehouse_id = #{query.warehouseId}
AND b.sku_id = #{query.skuId}
AND k.sku_code ILIKE CONCAT('%', #{query.skuCode}, '%')
AND p.name ILIKE CONCAT('%', #{query.productName}, '%')
ORDER BY b.updated_at DESC, b.id DESC
